INSERT INTO shipments (tracking_number,user_id,courier_id,sender_name,sender_phone,pickup_address,receiver_name,receiver_phone,receiver_address,delivery_time,package_description,delivery_fee,status) VALUES ('SWIFT-DEV-001',(SELECT id FROM users WHERE email='customer1@swiftship.test'),NULL,'Test Sender','01000000004','Cairo warehouse','Test Receiver','01000000005','Giza address','2026-12-01 13:00:00','Sample package 1',26,'pending') ON DUPLICATE KEY UPDATE tracking_number=VALUES(tracking_number);
INSERT INTO shipment_history(shipment_id,old_status,new_status,notes,changed_by) SELECT s.id,NULL,'pending','Seed fixture',u.id FROM shipments s JOIN users u ON u.email='admin@swiftship.test' WHERE s.tracking_number='SWIFT-DEV-001' AND NOT EXISTS(SELECT 1 FROM shipment_history h WHERE h.shipment_id=s.id);
